CREATE TABLE IF NOT EXISTS map_reference_backup_300 AS SELECT * FROM idea_references WHERE kind='stage';
CREATE TABLE map_reference_import_300 (title TEXT PRIMARY KEY, content TEXT NOT NULL);
INSERT INTO map_reference_import_300 VALUES ('深海水族館鬼ごっこ','');
UPDATE map_reference_import_300 SET content=content||'{"brief":"マップ全体の制作目標：約300×300ブロック（約90,000ブロック平方）。建物1棟の寸法ではなく、周辺施設・屋外・道路を含む遊べる敷地全体です。複数の建物、広場、周回路、近道を配置して広く逃げ回れる構成にします。図中の50×50区画は配置を考える目安です。\nAI生成のMinecraft風設計イメージ。Java 1.21.1／Fabric想定。実在ワールドの画像や正確な測量図ではありません。図の建物数・細部・経路・数字は候補で、企画本文と隠しアイテム6つの設定を優先します。装飾の像と、企画の対象となる城主の石像は区別してください。正確な座標・ブロック数・鬼の通行幅・高さ・到達性は実制作で確認します。","images":[{"data":"data:image/webp;base64,' WHERE title='深海水族館鬼ごっこ';
