INSERT INTO idea_references (idea_id,kind,content)
SELECT ideas.id,'stage',map_reference_import_300.content FROM ideas JOIN map_reference_import_300 ON ideas.title=map_reference_import_300.title WHERE 1
ON CONFLICT(idea_id,kind) DO UPDATE SET content=excluded.content;
DROP TABLE map_reference_import_300;